// D4-04: the README's benchmark numbers ARE the CSV's. The block between the bench markers is
// regenerated by scripts/bench-readme.mjs from docs/benchmarks/vector-index.csv and this test
// recomputes it and demands equality, so a figure cannot be edited by hand or left stale. It also
// pins the claims the README must make (machine, "not measured" for 8 GB, limitations) and the section
// order.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { BEGIN, COLUMNS, END, parseCsv, renderBench, summarise } from '../scripts/bench-csv.mjs';

const root = join(import.meta.dirname, '..');
const readme = readFileSync(join(root, 'README.md'), 'utf8');
const csvText = readFileSync(join(root, 'docs', 'benchmarks', 'vector-index.csv'), 'utf8');
const rows = parseCsv(csvText);

function block(): string {
  const a = readme.indexOf(BEGIN);
  const b = readme.indexOf(END);
  expect(a, 'README has the bench:begin marker').toBeGreaterThanOrEqual(0);
  expect(b, 'README has the bench:end marker').toBeGreaterThan(a);
  return readme.slice(a + BEGIN.length, b).trim();
}

describe('docs/benchmarks/vector-index.csv', () => {
  it('has the documented header and at least one row', () => {
    expect(csvText.split('\n')[0]).toBe(COLUMNS.join(','));
    expect(rows.length).toBeGreaterThan(0);
  });

  it('every row matched the naive reference, ran with precise memory info, and has generated provenance', () => {
    for (const r of rows) {
      expect(r['match'], `${r['driver']} ${r['rows']} run ${r['run']}`).toBe('true');
      expect(r['precise_memory']).toBe('true');
      expect(r['commit']).toMatch(/^[0-9a-f]{7,40}(-dirty)?$/);
      expect(r['machine']).toMatch(/^.+, \d+ GB$/);
      expect(r['date_utc']).toMatch(/^\d{4}-\d\d-\d\dT/);
      expect(Number(r['dim'])).toBe(384);
      for (const c of ['write_ms', 'cold_open_ms', 'first_query_ms', 'cold_total_ms'])
        expect(Number(r[c]), c).toBeGreaterThan(0);
      expect(Number(r['cold_total_ms'])).toBeCloseTo(
        Number(r['cold_open_ms']) + Number(r['first_query_ms']),
        0,
      );
    }
    expect(
      new Set(rows.map((r) => r['commit'])).size,
      'one commit value per run of the script',
    ).toBe(1);
  });

  it('covers OPFS 100k at both chunk sizes (5 cold runs and 1 restart run each) and 10k on OPFS and IndexedDB', () => {
    const cfg = (driver: string, n: number, chunk: number) =>
      rows.filter(
        (r) =>
          r['driver'] === driver && Number(r['rows']) === n && Number(r['chunk_bytes']) === chunk,
      );
    for (const chunk of [256, 2048]) {
      const g = cfg('opfs', 100000, chunk);
      expect(
        g.filter((r) => r['restart'] === 'false').length,
        `cold runs at ${chunk} B`,
      ).toBeGreaterThanOrEqual(5);
      expect(
        g.filter((r) => r['restart'] === 'true').length,
        `restart run at ${chunk} B`,
      ).toBeGreaterThanOrEqual(1);
    }
    expect(cfg('opfs', 10000, 256).length).toBeGreaterThanOrEqual(6);
    expect(cfg('indexeddb', 10000, 256).length).toBeGreaterThanOrEqual(6);
  });
});

describe('README benchmarks', () => {
  it('the generated block equals what the CSV renders to (numbers come from the CSV only)', () => {
    expect(block()).toBe(renderBench(rows).trim());
  });

  it('names the machine, the commit base and says "not measured on 8 GB"', () => {
    expect(readme).toContain('Apple M5 Pro, 48 GB');
    expect(readme).toContain('not measured on 8 GB');
    const base = String(rows[0]!['commit']).replace(/-dirty$/, '');
    // the vector rows were measured in Sprint 4 and are not re-measured: the wording says so
    expect(readme).toContain(`on the uncommitted Sprint 4 working tree based on ${base}`);
  });

  it('every 8 GB cell reads exactly "not measured on 8 GB" and every table row has one', () => {
    const lines = block()
      .split('\n')
      .filter((l) => l.startsWith('| ') && !l.startsWith('| ---') && !l.startsWith('| Index'));
    expect(lines.length).toBeGreaterThanOrEqual(rows.length > 0 ? 3 : 0);
    const withCell = lines.filter((l) => l.trimEnd().endsWith('| not measured on 8 GB |'));
    // the cold table and the memory table carry the column; the "where the time goes" table does not
    expect(withCell.length).toBe(summarise(rows).length * 2);
  });

  it('every localdata figure names its chunk size', () => {
    const lines = block()
      .split('\n')
      .filter((l) => l.startsWith('| ') && !l.startsWith('| ---') && !l.startsWith('| Index'));
    for (const l of lines) expect(l).toMatch(/\d-byte chunks/);
  });

  it('states the done-when verdict wording from the CSV, never a plain "met"', () => {
    const b = block();
    expect(b).toMatch(
      /Done-when \(100,000 chunks persist and reload cold in under 2 seconds\): (passes|does NOT pass) on this machine/,
    );
    expect(b).toContain('headroom');
    expect(b).toContain('Apple M5 Pro, 48 GB; not measured on 8 GB');
  });

  it('keeps the ten README sections of the Sprint 5 conventions, in order, and no others', () => {
    const h2 = [...readme.matchAll(/^## (.+)$/gm)].map((m) => m[1]);
    expect(h2).toEqual([
      'Status',
      'What it does',
      'Install',
      'Usage',
      'Demo',
      'Benchmarks',
      'Limitations',
      'Security',
      'Licence',
      'Contributing',
    ]);
  });

  it('opens its Status with the Sprint 5 status line (Working: ... Not yet: ...)', () => {
    const status = readme.slice(readme.indexOf('\n## Status'), readme.indexOf('\n## What it does'));
    expect(status).toMatch(/\nSprint 5 \(18 Nov 2026\): Working: .+\. Not yet: .+\.\n/);
  });

  it('Limitations states every item the plan requires', () => {
    const lim = readme.slice(readme.indexOf('\n## Limitations'), readme.indexOf('\n## Security'));
    const need = [
      'single writer per namespace',
      'stale',
      'no compaction',
      'f32 only',
      'CRC-32C detects accidental corruption, truncation and torn writes; it does not detect a deliberate edit by anyone who can write the browser profile, who can recompute it.',
      "Embeddings, keys and chunk values are stored unencrypted in this origin's OPFS or IndexedDB",
      'A flat index has no defence against poisoning: a document crafted to rank first for many queries will rank first.',
      "Browser storage eviction removes the whole origin's data, so the index disappears rather than becoming partly corrupt.",
      'WebAssembly memory does not shrink until the store is closed',
      'clear(ns)',
      'not an 8 GB figure',
      'IndexedDB',
      // Sprint 5 (D4-05)
      'no HNSW',
      'TD-17',
      'no encryption at rest',
      'deleteDocument hides',
      'only clear(ns) removes',
    ];
    for (const n of need) expect(lim.toLowerCase(), n).toContain(n.toLowerCase());
  });

  it('adds no compliance claim: every "complian" in the README is a negation', () => {
    for (const m of readme.matchAll(/[^\n]*complian[^\n]*/gi)) {
      expect(m[0], m[0]).toMatch(/\b(not|no|never|makes no|nothing)\b/i);
    }
  });
});
